import {tokenize,focalIndex,sentenceJump,delayFor,unzip} from './core.js';
const $=id=>document.getElementById(id);let book,words=[],chapters=[],index=0,playing=false,timer,library=[],db,contextParagraph=-1,wakeLock;let speed=300,chunk=1,pauses=true,focal=true;
const storage={get(k){try{return localStorage.getItem(k);}catch{return null;}},set(k,v){try{localStorage.setItem(k,v);}catch{}}};
try{const s=JSON.parse(storage.get('speedread.settings')||'{}');speed=Math.max(100,Math.min(1000,Number(s.speed)||300));chunk=[1,2,3].includes(s.chunk)?s.chunk:1;pauses=s.pauses!==false;focal=s.focal!==false;if(s.dark)document.body.classList.add('dark');}catch{}
function settings(){storage.set('speedread.settings',JSON.stringify({speed,chunk,pauses,focal,dark:document.body.classList.contains('dark')}));}
function notify(message){$('toast').textContent=message;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500);}
function persist(){if(book)storage.set('speedread.position.'+book.id,String(index));}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('speedread',1);r.onupgradeneeded=()=>r.result.createObjectStore('books',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbRequest(method,value){return new Promise((resolve,reject)=>{const tx=db.transaction('books',method==='getAll'?'readonly':'readwrite');const r=tx.objectStore('books')[method](...(value===undefined?[]:[value]));tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);});}
function setBook(b){pause();book=b;({words,chapters}=tokenize(b));index=Math.max(0,Math.min(words.length-1,Number(storage.get('speedread.position.'+b.id))||0));contextParagraph=-1;storage.set('speedread.lastBook',b.id);$('title').textContent=$('sideTitle').textContent=b.title;$('author').textContent=$('sideAuthor').textContent=b.author||'Your library';$('chapter').replaceChildren(...chapters.map((c,i)=>new Option(c.title,String(i))));$('progress').max=Math.max(0,words.length-1);$('play').disabled=!words.length;showView('reader');render();}
function render(){if(!words.length)return;const current=words[index];const displayed=words.slice(index,index+chunk);const el=$('word');el.replaceChildren();el.classList.toggle('chunked',chunk>1||!focal);if(chunk===1&&focal){const chars=Array.from(current.text),pivot=focalIndex(current.text);for(const [tag,text] of [['span',chars.slice(0,pivot).join('')],['em',chars[pivot]],['span',chars.slice(pivot+1).join('')]]){const node=document.createElement(tag);node.textContent=text;el.append(node);}}else el.textContent=displayed.map(w=>w.text).join(' ');const length=displayed.map(w=>w.text).join(' ').length;el.style.fontSize=chunk===1&&focal?`clamp(24px, ${Math.min(64,Math.max(26,500/Math.max(8,length)))}px, 10vw)`:`clamp(20px, ${Math.min(44,500/Math.max(12,length))}px, 7vw)`;$('chapter').value=String(current.chapter);$('progress').value=index;const percent=Math.round(index/Math.max(1,words.length-1)*100);$('position').textContent=`${percent}% complete · ${(index+1).toLocaleString()} of ${words.length.toLocaleString()} words`;$('remaining').textContent=`~${Math.ceil((words.length-index)/speed)} min left`;$('caption').textContent=playing?'Settle in. Follow the focal point.':index===words.length-1?'End of book. A story well spent.':'Your place is saved. Continue whenever you like.';renderContext();}
function renderContext(){const p=words[index].paragraph;if(p!==contextParagraph){contextParagraph=p;const fragment=document.createDocumentFragment();let start=index;while(start>0&&words[start-1].paragraph===p)start--;const end=Math.min(words.length,start+1000);$('context').replaceChildren();for(let i=start;i<end&&words[i].paragraph===p;i++){const btn=document.createElement('button');btn.textContent=words[i].text;btn.dataset.index=i;btn.onclick=()=>seek(i);fragment.append(btn,document.createTextNode(' '));}$('context').append(fragment);}for(const el of $('context').querySelectorAll('.current'))el.classList.remove('current');const selected=$('context').querySelector(`[data-index="${index}"]`);if(selected){selected.classList.add('current');if(!$('context').hidden){const top=selected.offsetTop-$('context').offsetTop;if(top<$('context').scrollTop||top>$('context').scrollTop+$('context').clientHeight-30)$('context').scrollTop=Math.max(0,top-35);}}}
function pause(){clearTimeout(timer);playing=false;$('play').innerHTML='▶ <span>Continue reading</span>';if(wakeLock){wakeLock.release().catch(()=>{});wakeLock=null;}persist();if(words.length)render();}
async function play(){if(!words.length)return;if(playing){pause();return;}if(index>=words.length-1)index=0;playing=true;$('play').innerHTML='Ⅱ <span>Pause</span>';render();schedule();try{if(navigator.wakeLock){const lock=await navigator.wakeLock.request('screen');if(playing)wakeLock=lock;else await lock.release();}}catch{}}
function schedule(){clearTimeout(timer);const displayed=words.slice(index,index+chunk);timer=setTimeout(()=>{if(!playing)return;if(index+chunk>=words.length){index=words.length-1;pause();notify('Book complete.');return;}index+=chunk;persist();render();schedule();},delayFor(displayed,speed,pauses));}
function seek(n){pause();index=Math.max(0,Math.min(words.length-1,n));persist();render();}
function showView(name){pause();$('readerView').hidden=name!=='reader';$('libraryView').hidden=name!=='library';$('readerNav').classList.toggle('active',name==='reader');$('libraryNav').classList.toggle('active',name==='library');if(name==='library')renderLibrary();}
function renderLibrary(){$('bookCount').textContent=library.length;$('books').replaceChildren();for(const b of library){const card=document.createElement('article');card.className='library-book';const cover=document.createElement('div');cover.className='book-cover';cover.textContent=b.title;const by=document.createElement('small');by.textContent=b.author||'YOUR LIBRARY';cover.append(by);const title=document.createElement('h2');title.textContent=b.title;const stats=document.createElement('small');const count=tokenize(b).words.length;stats.textContent=`${count.toLocaleString()} words · ${Math.ceil(count/speed)} min`;const read=document.createElement('button');read.className='button';read.textContent='Open book →';read.onclick=()=>setBook(b);card.append(cover,title,stats,read);if(b.id!=='carmen'){const del=document.createElement('button');del.className='delete-book';del.textContent='Remove from library';del.onclick=async()=>{if(!confirm(`Remove “${b.title}” from this device?`))return;try{if(db)await dbRequest('delete',b.id);library=library.filter(x=>x.id!==b.id);if(book.id===b.id)setBook(library[0]);showView('library');}catch{notify('Could not remove this book.');}};card.append(del);}$('books').append(card);}}
async function addBook(b){if(!tokenize(b).words.length)throw Error('No readable text found.');if(db){await dbRequest('put',b);}else notify('Device storage is unavailable. This book is available until you close the app.');library.push(b);renderLibrary();setBook(b);$('importDialog').close();$('paste').value='';$('pasteTitle').value='';}
function plainBook(text,title){return{id:crypto.randomUUID(),title,author:'Imported text',chapters:[{title:'Full text',paragraphs:text.split(/\n\s*\n/).filter(x=>x.trim())}]};}
function parseXML(text){const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw Error('This EPUB contains invalid XML.');return doc;}
function resolvePath(base,relative){return decodeURIComponent(new URL(relative,'https://epub.local/'+base).pathname.slice(1));}
async function parseEPUB(file){const files=await unzip(await file.arrayBuffer());const container=files.get('META-INF/container.xml');if(!container)throw Error('The EPUB container is missing.');const root=parseXML(await container()).getElementsByTagNameNS('*','rootfile')[0]?.getAttribute('full-path');if(!root||!files.has(root))throw Error('The EPUB package is missing.');const pkg=parseXML(await files.get(root)());const items=new Map(Array.from(pkg.getElementsByTagNameNS('*','item')).map(e=>[e.getAttribute('id'),e]));const title=pkg.getElementsByTagNameNS('*','title')[0]?.textContent||file.name.replace(/\.epub$/i,'');const author=pkg.getElementsByTagNameNS('*','creator')[0]?.textContent||'Imported EPUB';const chapters=[];for(const ref of pkg.getElementsByTagNameNS('*','itemref')){if(ref.getAttribute('linear')==='no')continue;const item=items.get(ref.getAttribute('idref'));if(!item||!['application/xhtml+xml','text/html'].includes(item.getAttribute('media-type')))continue;const path=resolvePath(root,item.getAttribute('href'));if(!files.has(path))throw Error('A chapter file is missing from the EPUB.');const doc=new DOMParser().parseFromString(await files.get(path)(),'text/html');doc.querySelectorAll('script,style,nav,header,footer,#pg-header,#pg-footer,.pg-boilerplate,svg').forEach(e=>e.remove());let chapter={title:`Section ${chapters.length+1}`,paragraphs:[]};for(const e of doc.body.querySelectorAll('h1,h2,h3,p,li,blockquote,pre')){if(e.parentElement?.closest('p,li,blockquote,pre'))continue;const t=e.textContent.replace(/\s+/g,' ').trim();if(!t)continue;if(/^H[123]$/.test(e.tagName)){if(chapter.paragraphs.length)chapters.push(chapter);chapter={title:t,paragraphs:[]};}else chapter.paragraphs.push(t);}if(chapter.paragraphs.length)chapters.push(chapter);else if(!doc.body.querySelector('p,li,blockquote,pre')){const t=doc.body.textContent.trim();if(t)chapters.push({title:chapter.title,paragraphs:[t]});}}return{id:crypto.randomUUID(),title,author,chapters};}
$('play').onclick=play;$('prev').onclick=()=>seek(sentenceJump(words,index,-1));$('next').onclick=()=>seek(sentenceJump(words,index,1));$('chapter').onchange=()=>seek(chapters[Number($('chapter').value)].start);$('progress').oninput=()=>seek(Number($('progress').value));$('speed').value=speed;$('speedNumber').textContent=speed;$('chunk').value=chunk;$('pauses').checked=pauses;$('focal').checked=focal;$('speed').oninput=()=>{speed=Number($('speed').value);$('speedNumber').textContent=speed;settings();render();if(playing)schedule();};$('chunk').onchange=()=>{chunk=Number($('chunk').value);settings();render();if(playing)schedule();};$('pauses').onchange=()=>{pauses=$('pauses').checked;settings();if(playing)schedule();};$('focal').onchange=()=>{focal=$('focal').checked;settings();render();};function themeLabel(){$('theme').innerHTML=document.body.classList.contains('dark')?'☀ <span>Light mode</span>':'☾ <span>Dark mode</span>';}themeLabel();$('theme').onclick=()=>{document.body.classList.toggle('dark');themeLabel();settings();};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('readerView').requestFullscreen();}catch{notify('Full screen is unavailable here. On iPhone, add Speedread to your Home Screen.');}};$('contextToggle').onclick=()=>{$('context').hidden=!$('context').hidden;$('contextToggle').textContent=$('context').hidden?'Show passage ＋':'Hide passage −';};$('readerNav').onclick=()=>showView('reader');$('libraryNav').onclick=()=>showView('library');function openImport(){pause();$('importStatus').textContent='';$('file').value='';$('importDialog').showModal();}$('importOpen').onclick=$('libraryImport').onclick=openImport;
$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;$('importStatus').textContent='Opening your book…';$('file').disabled=true;try{if(file.size>25*1024*1024)throw Error('Please choose a book smaller than 25 MB.');let b;if(/\.epub$/i.test(file.name))b=await parseEPUB(file);else if(/\.txt$/i.test(file.name))b=plainBook(await file.text(),file.name.replace(/\.txt$/i,''));else throw Error('Choose an EPUB or TXT file. PDF import is not available in this version.');await addBook(b);}catch(e){$('importStatus').textContent=e.message;}finally{$('file').disabled=false;}};
$('pasteImport').onclick=async()=>{try{await addBook(plainBook($('paste').value,$('pasteTitle').value.trim()||'Pasted reading'));}catch(e){$('importStatus').textContent=e.message;}};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName)||$('importDialog').open||$('readerView').hidden)return;if(e.code==='Space'){e.preventDefault();play();}else if(e.key==='ArrowLeft'){e.preventDefault();$('prev').click();}else if(e.key==='ArrowRight'){e.preventDefault();$('next').click();}});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('pagehide',persist);
try{db=await openDB();}catch{notify('Storage is unavailable; reading progress may not persist.');}
try{const response=await fetch('books/carmen.json');if(!response.ok)throw Error('Could not load Carmen. Please reload.');const carmen=await response.json();library=[carmen];if(db){try{library.push(...await dbRequest('getAll'));}catch{notify('Saved books could not be opened.');}}renderLibrary();setBook(library.find(b=>b.id===storage.get('speedread.lastBook'))||carmen);}catch(e){$('position').textContent=e.message;}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

// iPhone Home Screen apps do not reliably implement the Fullscreen API. This
// viewport-filling focus mode keeps the reader controls usable in every browser.
const focusStyles=document.createElement('style');
focusStyles.textContent=`.word span:first-child{width:auto;flex:1 1 0;min-width:0}.word em{width:auto;flex:0 0 auto}.word span:last-child{flex:1 1 0;min-width:0}body.focus-mode-active{overflow:hidden}#readerView.focus-mode{position:fixed;inset:0;z-index:100;display:flex;flex-direction:column;background:var(--bg);padding:max(16px,env(safe-area-inset-top)) max(16px,env(safe-area-inset-right)) max(16px,env(safe-area-inset-bottom)) max(16px,env(safe-area-inset-left));overflow:auto}#readerView.focus-mode .bookbar,#readerView.focus-mode .settings,#readerView.focus-mode .context-head,#readerView.focus-mode .context,#readerView.focus-mode footer{display:none}#readerView.focus-mode .reader-card{flex:1;display:flex;flex-direction:column;width:100%;max-width:1100px;min-height:0;margin:auto;border:0;box-shadow:none}#readerView.focus-mode .word-stage{flex:1;height:auto;min-height:260px}#readerView.focus-mode .progress-area{padding-bottom:max(22px,env(safe-area-inset-bottom))}`;
document.head.append(focusStyles);

function setFocusMode(enabled){
  const reader=$('readerView');
  const button=$('fullscreen');
  reader.classList.toggle('focus-mode',enabled);
  document.body.classList.toggle('focus-mode-active',enabled);
  button.textContent=enabled?'×':'⛶';
  button.setAttribute('aria-label',enabled?'Exit focus mode':'Enter focus mode');
  button.setAttribute('aria-pressed',String(enabled));
  button.title=enabled?'Exit focus mode':'Focus mode';
}

const focusButton=$('fullscreen');
focusButton.setAttribute('aria-label','Enter focus mode');
focusButton.setAttribute('aria-pressed','false');
focusButton.title='Focus mode';
focusButton.onclick=()=>setFocusMode(!$('readerView').classList.contains('focus-mode'));
$('readerNav').addEventListener('click',()=>setFocusMode(false));
$('libraryNav').addEventListener('click',()=>setFocusMode(false));
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'&&$('readerView').classList.contains('focus-mode')){
    event.preventDefault();
    setFocusMode(false);
  }
});
